import {normalizePlayer} from './player-profile.mjs';
import {idOf,ITEMS} from './model.mjs';
import {ensureRaid,raidParty} from './raid-model.mjs';
export class PartyNetwork {
 constructor(g){this.g=g;this.peer=null;this.host=null;this.players=[];this.connections=new Map();this.myId='solo';this.status='';this.guest=false;this.encounter=null;this.lobbyPlayers=[]}
 reset(){const peer=this.peer;this.peer=null;this.host=null;this.players=[];this.connections.clear();this.myId='solo';this.guest=false;this.encounter=null;this.lobbyPlayers=[];peer?.destroy()}
 refresh(){if(!this.g.mode&&['friends','den'].includes(this.g.page))this.g.render()}
 syncLobby(){if(this.guest)return;this.encounter=ensureRaid(this.g).encounter;const players=[raidParty(this.g),...this.players];this.broadcast({type:'raid-lobby',encounter:this.encounter,players});this.refresh()}
 create(){if(!window.Peer)return this.g.toast('Le service de salons est indisponible. Tu peux jouer avec des bots.');this.reset();this.encounter=ensureRaid(this.g).encounter;this.status='Création du salon…';this.g.route('friends');const peer=this.peer=new window.Peer();peer.on('open',id=>{if(this.peer!==peer)return;this.myId=id;this.status='Salon prêt. Les places libres seront complétées par des bots.';this.syncLobby()});peer.on('error',e=>{this.status='Connexion impossible : '+e.type;this.g.toast(this.status);this.refresh()});peer.on('connection',c=>{c.on('open',()=>{if(this.connections.size>=3||this.g.battle.active){c.send({type:'error',message:'Salon complet ou combat déjà commencé.'});setTimeout(()=>c.close(),200);return}this.connections.set(c.peer,c)});c.on('data',d=>this.handleGuest(c,d));c.on('close',()=>{if(this.peer!==peer)return;this.connections.delete(c.peer);this.players=this.players.filter(p=>p.pid!==c.peer);this.g.battle.removePlayer(c.peer);this.status='Un allié est parti : un bot prendra sa place.';this.syncLobby()})})}
 handleGuest(c,d){if(!this.connections.has(c.peer)||!d||typeof d!=='object')return;if(d.type==='ready'&&(!this.g.battle.active||this.g.battle.data?.over)){const keys=[...new Set(Array.isArray(d.keys)?d.keys:[])].filter(k=>/^\d{1,4}s?$/.test(String(k))&&this.g.dex[idOf(k)]).map(String).slice(0,1);if(!keys.length)return;const items={};for(const k of keys){const values=Array.isArray(d.items?.[k])?d.items[k]:[];items[k]=[...new Set(values)].filter(key=>ITEMS.some(i=>i.key===key)).slice(0,3)}const player=normalizePlayer(d.player);this.players=this.players.filter(p=>p.pid!==c.peer);this.players.push({pid:c.peer,name:player.name,avatar:player.avatar,keys,items,training:d.training||{}});c.send({type:'ready-accepted'});this.syncLobby()}if(d.type==='action')this.g.battle.remoteAction(c.peer,d.action,d.battleId)}
 join(code){code=code.trim();if(!code)return this.g.toast('Entre le code du salon.');if(!window.Peer)return this.g.toast('Le service de salons est indisponible.');this.reset();this.guest=true;this.status='Connexion au salon…';const peer=this.peer=new window.Peer();peer.on('open',id=>{if(this.peer!==peer)return;this.myId=id;this.host=peer.connect(code,{reliable:true});this.host.on('open',()=>this.sendReady());this.host.on('data',d=>{if(!d||typeof d!=='object')return;if(d.type==='error'){this.status=d.message;this.g.toast(d.message);this.refresh()}if(d.type==='ready-accepted'){this.status='Partenaire prêt. En attente de l’hôte.';this.refresh()}if(d.type==='raid-lobby'){this.encounter=d.encounter;this.lobbyPlayers=d.players||[];this.refresh()}if(d.type==='battle-end-room'){if(this.g.battle.active)this.g.battle.stop();return}if(typeof d.type==='string'&&d.type.startsWith('battle-'))this.g.battle.receive(d)});this.host.on('close',()=>{if(this.peer!==peer)return;this.guest=false;this.host=null;this.encounter=null;this.status='Le salon a été fermé.';if(this.g.battle.active)this.g.battle.stop();this.g.toast(this.status);this.refresh()})});peer.on('error',e=>{this.status='Connexion : '+e.type;this.g.toast(this.status);this.refresh()});this.refresh()}
 sendReady(){if(!this.host?.open)return;const p=raidParty(this.g);this.host.send({type:'ready',player:this.g.state.player,keys:p.keys,training:p.training,items:p.items});this.g.toast('Ton partenaire a été envoyé à l’hôte.')}
 broadcast(message){for(const c of this.connections.values())if(c.open)c.send(message)}
}
